"""Persona 444 (v3.10.1346): pressing Add on a receipt import that stays on the review (a row skipped, some left waiting) now shows its message where you are (toast + scrolled into view), and pressing it again never counts a done row twice. Invented data only."""
import sys; sys.path.insert(0, __file__.rsplit('/', 1)[0])
from harness import *
from playwright.sync_api import sync_playwright
f = Findings()
with fresh_server() as root, sync_playwright() as pw:
    page = pw.chromium.launch().new_context(viewport={'width': 390, 'height': 700}, service_workers='block').new_page(); errs = []
    page.on('pageerror', lambda e: errs.append(str(e)[:200])); page.on('dialog', lambda d: d.accept())
    page.goto('http://localhost:5757/'); page.wait_for_timeout(1200); ev = page.evaluate
    ev("state.onboarded=true; saveState()"); ev("document.getElementById('onboardingOverlay')?.remove()")
    ev("mhShopOpen()"); ev("mhOrdOpen('receipt')"); page.wait_for_timeout(200)
    page.fill('#mhOrdText', "Cheddar 400g\n2.00\nPlain Rice 1kg\n1.00\nOat Milk 1l\n1.20\n"); page.click('#mhOrdRead'); page.wait_for_timeout(400)
    ev("mhShopRender()")
    rows = ev("_shopUi.ord.rows.map(r=>r.track)")
    lvl = lambda n: ev("n=>{const e=Object.entries(mhStockLoad().items).find(([k])=>k.startsWith(n.toLowerCase())); return e ? e[1].level : null}", n)
    ev("mhOrdSet(0,'amount','400 g'); mhOrdSet(1,'amount','1000 g'); mhOrdSet(2,'amount',''); mhShopRender()"); page.wait_for_timeout(200)
    page.evaluate("document.querySelector('#mhOrdGo').scrollIntoView()"); page.click('#mhOrdGo'); page.wait_for_timeout(900)
    if not ev("!!document.getElementById('mhShopMsg')"): f.add('BUG', '1: no message after a partial add')
    if not ev("(()=>{const e=document.querySelector('[data-ord=\"2\"]'); if(!e) return false; const r=e.getBoundingClientRect(); return r.bottom>0 && r.top<innerHeight})()"): f.add('BUG', '2: the first row to check is not in view')
    if lvl(rows[0]) != 400 or lvl(rows[1]) != 1000: f.add('BUG', f'3: the two good rows are added: {lvl(rows[0])} {lvl(rows[1])}')
    page.evaluate("document.querySelector('#mhOrdGo').scrollIntoView()"); page.click('#mhOrdGo'); page.wait_for_timeout(700)
    if lvl(rows[0]) != 400 or lvl(rows[1]) != 1000: f.add('BUG', f'4: a second press counted twice: {lvl(rows[0])} {lvl(rows[1])}')
    if not ev("!!document.getElementById('mhShopMsg')"): f.add('BUG', '5: no message on the second press')
    if errs: f.add('BUG', f'errors {errs[:2]}')
# a closest-guess row is held back, the screen goes to it, Use this then lets it in
    ev("mhOrdOpen('receipt')") if not ev("!!_shopUi.ord") else None
    ev("(()=>{const r=_shopUi.ord.rows[2]; r.on=true; r.from='closest in your library'; r.track='Oat Milk'; r.amount='1000 ml'; mhShopRender()})()"); page.wait_for_timeout(200)
    if not ev("!!document.querySelector('[data-ord=\"2\"] button') && [...document.querySelectorAll('[data-ord=\"2\"] button')].some(b=>/Use this/.test(b.innerText))"): f.add('BUG', '6: guess row has Use this')
    page.evaluate("document.querySelector('#mhOrdGo').scrollIntoView()"); page.click('#mhOrdGo'); page.wait_for_timeout(1000)
    if lvl('Oat Milk') is not None: f.add('BUG', '7: a guess row was added without being checked')
    if not ev("(()=>{const e=document.querySelector('[data-ord=\"2\"]'); if(!e) return false; const r=e.getBoundingClientRect(); return r.bottom>0 && r.top<innerHeight})()"): f.add('BUG', '8: the screen is not on the first row to check')
    ev("mhOrdUseGuess(2)"); page.wait_for_timeout(200); page.evaluate("document.querySelector('#mhOrdGo').scrollIntoView()"); page.click('#mhOrdGo'); page.wait_for_timeout(900)
    if lvl('Oat Milk') != 1000: f.add('BUG', f'9: after Use this the row is added: {lvl("Oat Milk")}')
# settle a row: the screen moves to the next row that needs you; finishing goes to My cupboards
    ev("mhOrdDiscard && mhOrdDiscard()"); ev("mhShopOpen()"); ev("mhOrdOpen('receipt')"); page.wait_for_timeout(200)
    page.fill('#mhOrdText', "Cheddar Block 400g\n2.00\nPlain Rice Bag 1kg\n1.00\nOat Drink 1l\n1.20\n"); page.click('#mhOrdRead'); page.wait_for_timeout(400)
    ev("(()=>{const d=_shopUi.ord; d.rows.forEach(r=>{r.done=false}); d.rows[0].from='closest in your library'; d.rows[1].from='closest in your library'; d.rows[0].track='Cheddar'; d.rows[1].track='Plain Rice'; d.rows[0].amount='400 g'; d.rows[1].amount='1000 g'; d.rows[2].amount='1 l'; d.rows[0].on=d.rows[1].on=d.rows[2].on=true; mhShopRender()})()"); page.wait_for_timeout(200)
    ev("mhOrdUseGuess(0)"); page.wait_for_timeout(900)
    if ev("_shopUi.view") != 'orderimport': f.add('BUG', f'11: still on the review: {ev("_shopUi.view")}')
    ev("mhOrdUseGuess(1)"); page.wait_for_timeout(300); page.evaluate("document.querySelector('#mhOrdGo').scrollIntoView()"); page.click('#mhOrdGo'); page.wait_for_timeout(900)
    if ev("_shopUi.ord") is None and ev("_shopUi.view") != 'stocklist': f.add('BUG', f'12: finished but not on My cupboards: {ev("_shopUi.view")}')
# non-food lines are never held for a food guess, and a generic non-food list line comes off the shopping list
    ev("mhOrdDiscard && mhOrdDiscard()"); ev("mhShopOpen()")
    ev("(()=>{const s=mhShopLoad(); mhShopSetAdd(s,'Shampoo','manual','',null,{nonFood:true}); mhShopSave(s)})()")
    ev("mhOrdOpen('receipt')"); page.wait_for_timeout(200)
    page.fill('#mhOrdText', "1 x TRESemme Rich Moisture Shampoo 680ml\n"); page.click('#mhOrdRead'); page.wait_for_timeout(400)
    ev("(()=>{const r=_shopUi.ord.rows[0]; r.kind='nonfood'; r.from='closest in your library'; r.on=true; mhShopRender()})()")
    page.evaluate("document.querySelector('#mhOrdGo').scrollIntoView()"); page.click('#mhOrdGo'); page.wait_for_timeout(900)
    if ev("!!_shopUi.ord"): f.add('BUG', '13: a non-food guess row was held back')
    if ev("mhShopLoad().items.some(i=>/shampoo/i.test(i.name))"): f.add('BUG', '14: the Shampoo list line is still on the shopping list')
# some added, the rest unticked: Finish leaves them out and goes to My cupboards
    ev("mhOrdDiscard && mhOrdDiscard()"); ev("mhShopOpen()"); ev("mhOrdOpen('receipt')"); page.wait_for_timeout(200)
    page.fill('#mhOrdText', "Cheddar Block 400g\n2.00\nBanana Loaf Cake\n1.00\n"); page.click('#mhOrdRead'); page.wait_for_timeout(400)
    ev("(()=>{const d=_shopUi.ord; d.rows[0].amount='400 g'; d.rows[0].on=true; d.rows[1].on=false; mhShopRender()})()")
    page.evaluate("document.querySelector('#mhOrdGo').scrollIntoView()"); page.click('#mhOrdGo'); page.wait_for_timeout(900)
    if ev("!!_shopUi.ord") or ev("_shopUi.view") != 'stocklist': f.add('BUG', f'15: with only unticked lines left the import does not finish: ord {ev("!!_shopUi.ord")} view {ev("_shopUi.view")}')
    ev("mhOrdDiscard && mhOrdDiscard()"); ev("mhShopOpen()"); ev("mhOrdOpen('receipt')"); page.wait_for_timeout(200)
    page.fill('#mhOrdText', "Cheddar Slice 400g\n2.00\nBanana Loaf Cake\n1.00\n"); page.click('#mhOrdRead'); page.wait_for_timeout(400)
    ev("(()=>{const d=_shopUi.ord; d.rows[0].amount='400 g'; d.rows[0].on=true; d.rows[1].on=false; mhShopRender(); mhOrdApply(0)})()"); page.wait_for_timeout(500)
    if not ev("!!_shopUi.ord"): f.add('BUG', '16: setup: one row added, the import should still be open')
    else:
        page.evaluate("document.querySelector('#mhOrdGo').scrollIntoView()"); page.click('#mhOrdGo'); page.wait_for_timeout(900)
        if ev("!!_shopUi.ord") or ev("_shopUi.view") != 'stocklist': f.add('BUG', f'17: a second press with only unticked lines left does not finish: view {ev("_shopUi.view")}')
# add as you go: one row, then a section's ticked rows; the screen stays where it is
    ev("mhOrdDiscard && mhOrdDiscard()"); ev("mhShopOpen()"); ev("mhOrdOpen('receipt')"); page.wait_for_timeout(200)
    page.fill('#mhOrdText', "Mild Cheddar 400g\n2.00\nBasmati Rice 1kg\n1.00\nGreek Yoghurt 500g\n1.00\nBanana Cake\n1.00\n"); page.click('#mhOrdRead'); page.wait_for_timeout(400)
    ev("(()=>{const d=_shopUi.ord; d.rows[0].amount='400 g'; d.rows[1].amount='1000 g'; d.rows[2].amount='500 g'; d.rows.forEach((r,i)=>{r.on=i<3; if(r.from==='closest in your library') r.from='picked by you'}); mhShopRender()})()"); page.wait_for_timeout(200)
    if not page.get_by_text('＋ Add this one').count(): f.add('BUG', '18: no Add this one button on a ready row')
    y0 = ev("scrollY"); ev("mhOrdApplyRow(0)"); page.wait_for_timeout(500)
    if not ev("_shopUi.ord.rows[0].done") or ev("_shopUi.ord.rows[1].done"): f.add('BUG', '19: Add this one adds just that row')
    if not ev("!!document.querySelector('[data-ord=\"0\"][data-done]')"): f.add('BUG', '20: the added row collapses to a one-line Added')
    if ev("_shopUi.view") != 'orderimport': f.add('BUG', '21: still on the review after adding one')
    if ev("!!document.querySelector('[data-ord-sec]')") and not page.get_by_text('Add ticked').count(): f.add('BUG', '22: no Add ticked on the section')
    ev("(()=>{const d=_shopUi.ord; mhOrdApplySec(mhOrdSec(d.rows[1], d))})()"); page.wait_for_timeout(500)
    if not ev("_shopUi.ord.rows[1].done") or ev("_shopUi.ord.rows[3].done") or (ev("mhOrdSec(_shopUi.ord.rows[2], _shopUi.ord)!==mhOrdSec(_shopUi.ord.rows[1], _shopUi.ord)") and ev("_shopUi.ord.rows[2].done")): f.add('BUG', '23: Add ticked adds the ticked rows of its own section only')
    if ev("_shopUi.view") != 'orderimport': f.add('BUG', '24: still on the review after a section add')
print('findings', len(f)); [print(x) for x in f] if f else None; sys.exit(1 if f else 0)
